// Turns a Google Ads lead form webhook body into one lead record.
// Google sends each answer in user_column_data as { column_id, column_name, string_value }.
const settings = $('Settings').first().json;

// Google's standard column IDs, mapped to our columns. First match wins.
const FIELDS = {
  full_name: ['FULL_NAME'],
  first_name: ['FIRST_NAME'],
  last_name: ['LAST_NAME'],
  email: ['EMAIL', 'WORK_EMAIL'],
  phone: ['PHONE_NUMBER', 'WORK_PHONE'],
  company: ['COMPANY_NAME'],
  job_title: ['JOB_TITLE'],
  city: ['CITY'],
  postal_code: ['POSTAL_CODE'],
};
const MAPPED = new Set(Object.values(FIELDS).flat());

const clean = (v) => (v === null || v === undefined ? '' : String(v).trim());

function splitName(full) {
  const parts = full.split(/\s+/).filter(Boolean);
  if (parts.length < 2) return ['', parts[0] || ''];
  return [parts.slice(0, -1).join(' '), parts[parts.length - 1]];
}

const leads = [];
for (const [index, item] of $input.all().entries()) {
  const body = item.json.body || {};
  const answers = {};
  const other = {};
  for (const col of body.user_column_data || []) {
    const id = clean(col.column_id).toUpperCase();
    const value = clean(col.string_value);
    if (!value) continue;
    if (MAPPED.has(id)) {
      if (!(id in answers)) answers[id] = value;
    } else {
      // Other standard fields and custom questions, keyed by their label.
      other[clean(col.column_name) || id] = value;
    }
  }

  const lead = {};
  for (const [column, ids] of Object.entries(FIELDS)) {
    lead[column] = ids.map((id) => answers[id]).find(Boolean) || '';
  }
  if (!lead.full_name) lead.full_name = [lead.first_name, lead.last_name].filter(Boolean).join(' ');
  if (!lead.first_name && !lead.last_name && lead.full_name) {
    [lead.first_name, lead.last_name] = splitName(lead.full_name);
  }

  const isTest = body.is_test === true || body.is_test === 'true';

  leads.push({
    json: {
      lead_id: clean(body.lead_id),
      source: 'Google Ads',
      created_time: clean(body.lead_submit_time) || new Date().toISOString(),
      full_name: lead.full_name,
      first_name: lead.first_name,
      last_name: lead.last_name,
      email: lead.email.toLowerCase(),
      phone: lead.phone,
      company: lead.company,
      job_title: lead.job_title,
      city: lead.city,
      postal_code: lead.postal_code,
      other_answers: Object.keys(other).length ? JSON.stringify(other) : '',
      form: clean(body.form_id),
      campaign: clean(body.campaign_id),
      ad: clean(body.adgroup_id) || clean(body.asset_group_id) || clean(body.creative_id),
      gclid: clean(body.gcl_id),
      is_test: isTest,
      sync_status: isTest && !settings.send_test_leads_to_salesforce ? 'test lead, not sent to Salesforce' : 'pending',
    },
    pairedItem: { item: index },
  });
}
return leads;

// Turns each Facebook Lead Ads Trigger item (Simplify Output on) into one lead record.
const settings = $('Settings').first().json;

// Facebook's standard question keys, mapped to our columns. First match wins.
const FIELDS = {
  full_name: ['full_name'],
  first_name: ['first_name'],
  last_name: ['last_name'],
  email: ['email', 'work_email'],
  phone: ['phone_number', 'work_phone_number'],
  company: ['company_name'],
  job_title: ['job_title'],
  city: ['city'],
  postal_code: ['zip_code', 'post_code', 'postal_code'],
};
const MAPPED = new Set(Object.values(FIELDS).flat());

const clean = (v) => (v === null || v === undefined ? '' : String(v).trim());

function splitName(full) {
  const parts = full.split(/\s+/).filter(Boolean);
  if (parts.length < 2) return ['', parts[0] || ''];
  return [parts.slice(0, -1).join(' '), parts[parts.length - 1]];
}

const leads = [];
for (const [index, item] of $input.all().entries()) {
  const fb = item.json;
  const data = fb.data || {};
  const lead = {};
  for (const [column, keys] of Object.entries(FIELDS)) {
    lead[column] = clean(keys.map((k) => data[k]).find((v) => clean(v) !== ''));
  }
  if (!lead.full_name) lead.full_name = [lead.first_name, lead.last_name].filter(Boolean).join(' ');
  if (!lead.first_name && !lead.last_name && lead.full_name) {
    [lead.first_name, lead.last_name] = splitName(lead.full_name);
  }

  // Answers to custom questions, keyed by the question's field name.
  const other = {};
  for (const [key, value] of Object.entries(data)) {
    if (!MAPPED.has(key) && clean(value) !== '') other[key] = clean(value);
  }

  // Meta's Lead Ads Testing Tool fills answers with dummy values that start with "<test lead".
  const isTest = Object.values(data).some((v) => /^<test lead/i.test(clean(v)));

  leads.push({
    json: {
      lead_id: clean(fb.id),
      source: 'Facebook Lead Ads',
      created_time: clean(fb.created_time) || new Date().toISOString(),
      full_name: lead.full_name,
      first_name: lead.first_name,
      last_name: lead.last_name,
      email: lead.email.toLowerCase(),
      phone: lead.phone,
      company: lead.company,
      job_title: lead.job_title,
      city: lead.city,
      postal_code: lead.postal_code,
      other_answers: Object.keys(other).length ? JSON.stringify(other) : '',
      form: clean(fb.form?.name) || clean(fb.form?.id),
      campaign: clean(fb.adset?.name) || clean(fb.adset?.id),
      ad: clean(fb.ad?.name) || clean(fb.ad?.id),
      gclid: '',
      is_test: isTest,
      sync_status: isTest && !settings.send_test_leads_to_salesforce ? 'test lead, not sent to Salesforce' : 'pending',
    },
    pairedItem: { item: index },
  });
}
return leads;

// Builds one SOQL query that finds existing, unconverted Salesforce Leads for every email in this run.
const escapeSoql = (s) => String(s)
  .replace(/\\/g, '\\\\')
  .replace(/'/g, "\\'")
  .replace(/"/g, '\\"')
  .replace(/\n/g, '\\n')
  .replace(/\r/g, '\\r');

const items = $input.all();
const emails = [...new Set(items.map((i) => String(i.json.email || '').toLowerCase()).filter(Boolean))];

const soql = emails.length
  ? 'SELECT Id, Email, FirstName, LastName, Company, Phone, Title, City, PostalCode FROM Lead ' +
    `WHERE IsConverted = false AND Email IN (${emails.map((e) => `'${escapeSoql(e)}'`).join(', ')}) ` +
    'ORDER BY CreatedDate DESC'
  // No emails to look up, so run a query that returns nothing and every lead is created.
  : 'SELECT Id FROM Lead WHERE Id = null';

return items.map((item, index) => ({ json: { ...item.json, soql }, pairedItem: { item: index } }));

// Pairs each lead with the Salesforce Lead found by email, and prepares the Salesforce field values.
const settings = $('Settings').first().json;
const leads = $('Build Salesforce Lookup').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);

// Find Existing Leads continues on error, so a failed lookup arrives here as { error }.
const failed = results.find((r) => r.error);
const lookupError = failed ? [failed.error, failed.description].filter(Boolean).join(': ') : '';

// Newest unconverted Lead per email (the query sorts by CreatedDate, newest first).
const existingByEmail = {};
for (const r of results) {
  const key = String(r.Email || '').toLowerCase();
  if (r.Id && key && !existingByEmail[key]) existingByEmail[key] = r;
}

// Trim values to Salesforce's standard Lead field lengths so a long answer can't fail the sync.
const cut = (v, max) => String(v || '').trim().slice(0, max);

return leads.map((lead) => {
  const existing = existingByEmail[lead.email] || null;
  const fresh = {
    first_name: cut(lead.first_name, 40),
    last_name: cut(lead.last_name || lead.full_name, 80),
    company: cut(lead.company, 255),
    phone: cut(lead.phone, 40),
    title: cut(lead.job_title, 128),
    city: cut(lead.city, 40),
    postal_code: cut(lead.postal_code, 20),
  };

  let action = existing ? 'update' : 'create';
  if (lookupError) action = 'error';

  let fields;
  if (action === 'update') {
    // Keep what Salesforce already has when the new form left a field blank.
    fields = {
      first_name: fresh.first_name || existing.FirstName || '',
      last_name: fresh.last_name || existing.LastName || 'Unknown',
      company: fresh.company || existing.Company || settings.default_company,
      phone: fresh.phone || existing.Phone || '',
      title: fresh.title || existing.Title || '',
      city: fresh.city || existing.City || '',
      postal_code: fresh.postal_code || existing.PostalCode || '',
    };
  } else {
    fields = {
      ...fresh,
      last_name: fresh.last_name || 'Unknown',
      company: fresh.company || cut(settings.default_company, 255),
    };
  }

  let other = '';
  if (lead.other_answers) {
    try {
      other = Object.entries(JSON.parse(lead.other_answers)).map(([q, a]) => `${q}: ${a}`).join('\n');
    } catch (e) {
      other = lead.other_answers;
    }
  }
  const description = [
    `Lead from ${lead.source}.`,
    lead.form ? `Form: ${lead.form}` : '',
    lead.campaign ? `Campaign: ${lead.campaign}` : '',
    lead.ad ? `Ad: ${lead.ad}` : '',
    lead.gclid ? `GCLID: ${lead.gclid}` : '',
    `Lead ID: ${lead.lead_id}`,
    other ? `\nOther answers:\n${other}` : '',
  ].filter(Boolean).join('\n');

  return {
    json: {
      lead_id: lead.lead_id,
      sf_action: action,
      sf_id: existing ? existing.Id : '',
      email: cut(lead.email, 80),
      ...fields,
      lead_source: lead.source === 'Google Ads' ? settings.google_lead_source : settings.facebook_lead_source,
      description: description.slice(0, 32000),
      sync_error: lookupError,
    },
  };
});
